/*
 * Focused logic-level check of the guard added by CVE-2023-6606 fix.
 *
 * This does NOT compile the kernel source. It mirrors the target's
 * struct smb_hdr layout, BCC()/get_bcc() and the guard expression, and
 * asserts the guard boundary logic for positive and negative paths so the
 * arithmetic can be exercised without a kernel build.
 */
#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

struct smb_hdr {
	uint32_t smb_buf_length;
	uint8_t  Protocol[4];
	uint8_t  Command;
	uint8_t  Status[4];
	uint8_t  Flags;
	uint16_t Flags2;
	uint16_t PidHigh;
	uint8_t  Signature[8];
	uint8_t  pad[2];
	uint16_t Tid;
	uint16_t Pid;
	uint16_t Uid;
	uint16_t Mid;
	uint8_t  WordCount;
} __attribute__((packed));

static void *BCC(struct smb_hdr *smb)
{
	return (void *)smb + sizeof(*smb) + 2 * smb->WordCount;
}

static uint16_t get_bcc(struct smb_hdr *hdr)
{
	const unsigned char *p = (const unsigned char *)BCC(hdr);
	return (uint16_t)(p[0] | (p[1] << 8));
}

static unsigned int smbCalcSize(struct smb_hdr *ptr)
{
	return sizeof(struct smb_hdr) + 2 * ptr->WordCount + 2 + get_bcc(ptr);
}

/* returns 1 when the new guard rejects the frame */
static int guard_rejects(unsigned int total_read, struct smb_hdr *smb)
{
	return total_read < sizeof(*smb) + 2 * smb->WordCount;
}

int main(void)
{
	int failures = 0;
	struct smb_hdr hdr;
	hdr.WordCount = 10;
	unsigned int size = sizeof(struct smb_hdr);

	printf("sizeof(struct smb_hdr) = %u\n", size);
	printf("BCC offset for WordCount=10 = %zu\n", (size_t)((unsigned char *)BCC(&hdr) - (unsigned char *)&hdr));

	/* Negative path: frame reaches the header but not the declared words. */
	unsigned int short_read = 2 + size; /* passes the small-frame check, WordCount region absent */
	if (!guard_rejects(short_read, &hdr)) {
		printf("FAIL: negative path not rejected (total_read=%u)\n", short_read);
		failures++;
	} else {
		printf("PASS: rejected total_read=%u < sizeof+2*WordCount=%u (no smbCalcSize/get_bcc call)\n",
		       short_read, size + 2 * hdr.WordCount);
	}

	/* Positive path: frame covers exactly the declared word region. */
	unsigned int enough = size + 2 * hdr.WordCount;
	if (guard_rejects(enough, &hdr)) {
		printf("FAIL: positive path unexpectedly rejected (total_read=%u)\n", enough);
		failures++;
	} else {
		printf("PASS: accepted total_read=%u >= sizeof+2*WordCount=%u\n", enough, enough);
	}

	/* Boundary sweep around the guard threshold. */
	for (unsigned int r = size; r <= enough + 2; r++) {
		int rejected = guard_rejects(r, &hdr);
		int expected = (r < enough);
		if (rejected != expected) {
			printf("FAIL: boundary r=%u rejected=%d expected=%d\n", r, rejected, expected);
			failures++;
		}
	}
	printf("%s (failures=%d)\n", failures ? "LOGIC CHECK FAILED" : "LOGIC CHECK PASSED", failures);
	return failures ? 1 : 0;
}

